mapper.update:
update daily_recycle_stats
total_orders = #{totalOrders}, completed_orders = #{completedOrders}, cancelled_orders = #{cancelledOrders}, total_weight = #{totalWeight}, total_carbon_saved = #{totalCarbonSaved}, total_points_given = #{totalPointsGiven}, avg_response_time = #{avgResponseTime}, active_users = #{activeUsers}, active_collectors = #{activeCollectors}, appliance_type_stats = #{applianceTypeStats},
where id = #{id}

mapper.select:
select * from daily_recycle_stats
where stat_date between #{startDate} and #{endDate}
